using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using System.Text;using System.Security.Cryptography;using System.Web.Script.Serialization;
public static class ProvenanceAudit {
 public static string DescribeCard(Dictionary<string,object>card){var b=new StringBuilder("ПРОИСХОЖДЕНИЕ ВЫБРАННОЙ КАРТОЧКИ\r\nSEMANTICS_UNVERIFIED; DEMAND_UNVERIFIED; AUTO_ADMISSION=false\r\n");b.AppendLine("Карточка: "+S(card,"research_id")+" "+S(card,"candidate_id")+" | исходная job: "+S(card,"source_job")).AppendLine(card.ContainsKey("output_review")?"Тексты AI-карточки ниже — гипотезы/выводы модели, не наблюдения.":"Авторство текстов карточки здесь не установлено; это не подтверждённые факты.").AppendLine("Используются только источники, сохранённые В ЭТОЙ карточке. По E-ID с текущим корпусом не связываем. Наличие вложенного источника не доказывает смысловую поддержку каждого вывода.");foreach(string field in new[]{"title","buyer","problem_hypothesis","solution_hypothesis","alternatives_and_limits","validation_step"})if(S(card,field)!="")b.AppendLine().AppendLine("НЕДОКАЗАННЫЙ ТЕКСТ КАРТОЧКИ / "+field+": "+S(card,field));foreach(string field in new[]{"risks","missing_evidence"})foreach(var value in A(V(card,field)))b.AppendLine("НЕДОКАЗАННАЯ ИНТЕРПРЕТАЦИЯ / "+field+": "+value);int count=0;foreach(var x in A(V(card,"observed_basis"))){count++;var row=D(x);b.AppendLine().AppendLine("СОХРАНЁННЫЙ ИСТОЧНИК "+count+": "+S(row,"evidence_id")+" | "+S(row,"url")).AppendLine(DescribeObservation(row));if(S(row,"kind")=="public_topic_title"||S(row,"kind")=="public_question_title"){b.AppendLine("ТОЛЬКО ЗАГОЛОВОК: "+S(row,"title")).AppendLine("Тело недоступно. excerpt/заметка сборщика не подставляется как сообщение автора.");}else{foreach(string field in new[]{"context_text","answer_text"})if(S(row,field)!="")b.AppendLine(field+" — полный сохранённый текст:").AppendLine(S(row,field));}}if(count==0)b.AppendLine("Нет сохранённых исходных фрагментов. Утверждения не проверены.");foreach(var reportEntry in A(V(D(V(card,"buyer_demand_review")),"original_reports"))){var report=D(reportEntry);string url=S(report,"source_url"),text=S(report,"monetary_source_text");if(text=="")continue;bool member=A(V(card,"observed_basis")).Select(D).Any(x=>S(x,"url")==url);b.AppendLine().AppendLine("ДОПОЛНИТЕЛЬНЫЙ АРХИВНЫЙ ИСТОЧНИК — не подстановка в исходный вход AI");if(!member||S(report,"monetary_source_field_sha256")!=Sha(text)){b.AppendLine("Связь URL/hash не подтверждена; текст не предъявляется как проверенный фрагмент.");continue;}b.AppendLine(url).AppendLine("Автор (metadata): "+(V(report,"reported_author_id")==null?"не установлен":S(report,"reported_author_id"))).AppendLine("Поле: "+(S(report,"source_field")==""?"сохранённый нормализованный оригинал":S(report,"source_field"))+" | источник: "+S(report,"source_body_origin")).AppendLine("Сохранённая дата: "+S(report,"observed_at")+" | codepoint [0,"+Count(text)+") | SHA256: "+Sha(text)).AppendLine("Проверена целостность сохранённого текста, не его смысл и не спрос.").AppendLine(text);}
b.AppendLine("Не найденная буквальная опора не доказывает ложность; совпадение не доказывает смысл, покупателя, независимость или спрос.");return b.ToString();}
 internal static bool Equal(object a,object b){var da=a as Dictionary<string,object>;var db=b as Dictionary<string,object>;if(da!=null&&db!=null)return da.Count==db.Count&&da.All(x=>db.ContainsKey(x.Key)&&Equal(x.Value,db[x.Key]));if(a is IList&&b is IList){var aa=(IList)a;var bb=(IList)b;return aa.Count==bb.Count&&Enumerable.Range(0,aa.Count).All(i=>Equal(aa[i],bb[i]));}return object.Equals(a,b);}
 public static void ValidateBindings(Dictionary<string,object>catalog,Dictionary<string,object>output,Dictionary<string,object>input,Dictionary<string,object>response){var user=A(V(input,"messages")).Select(D).LastOrDefault(x=>S(x,"role")=="user");if(user==null)throw new InvalidDataException("Saved input user message missing");string text=S(user,"content");int start=text.IndexOf('{');if(start<0)throw new InvalidDataException("Saved input catalog missing");var json=new JavaScriptSerializer{MaxJsonLength=8388608,RecursionLimit=128};if(!Equal(catalog,json.DeserializeObject(text.Substring(start))))throw new InvalidDataException("Input catalog/URL/author snapshot mismatch; never join by E-ID alone");var choice=A(V(response,"choices")).Select(D).FirstOrDefault();if(choice==null||S(choice,"finish_reason")!="stop")throw new InvalidDataException("Saved model response incomplete");if(!Equal(output,json.DeserializeObject(S(D(V(choice,"message")),"content"))))throw new InvalidDataException("Output does not match archived raw response");}
 public sealed class Entry {public string CaseId,EvidenceId,Field,Role,Author,Url,Text;public bool SourceHashValid,ReferenceValid;public int CrossFieldMatches,ModelClaims;public override string ToString(){return CaseId+" | "+EvidenceId+" | "+Field+" | "+Role;}}
 static Dictionary<string,object> D(object o){return o as Dictionary<string,object>??new Dictionary<string,object>();}
 static object V(Dictionary<string,object>d,string k){return d.ContainsKey(k)?d[k]:null;}
 static string S(Dictionary<string,object>d,string k){return Convert.ToString(V(d,k));}
 static IEnumerable<object> A(object o){if(o is IEnumerable&&!(o is string)&&!(o is IDictionary))foreach(object x in (IEnumerable)o)yield return x;}
 public static string Sha(string text){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(Encoding.UTF8.GetBytes(text))).Replace("-","").ToLowerInvariant();}
 public static int Count(string x){int n=0;for(int i=0;i<x.Length;i++,n++)if(char.IsHighSurrogate(x[i])&&i+1<x.Length&&char.IsLowSurrogate(x[i+1]))i++;return n;}
 public static string Slice(string s,int start,int end){if(start<0||end<start||end>Count(s))throw new InvalidDataException("Invalid codepoint range");int a=0,b=0,c=0;for(int i=0;i<=s.Length;i++){if(c==start)a=i;if(c==end){b=i;break;}if(i<s.Length&&char.IsHighSurrogate(s[i])&&i+1<s.Length&&char.IsLowSurrogate(s[i+1]))i++;c++;}return s.Substring(a,b-a);}
 static string Role(Dictionary<string,object>row){string r=S(row,"field_role");if(r=="")r=S(row,"source_role");return r==""?"роль не сохранена":r;}
 static string Author(Dictionary<string,object>row){return V(row,"reported_author_id")==null||S(row,"reported_author_id")==""?"не установлен; не подставлять автора вопроса":S(row,"reported_author_id");}
 static string Body(Dictionary<string,object>row){return row.ContainsKey("text")?S(row,"text"):S(row,"full_text");}
 static string ExpectedHash(Dictionary<string,object>row){string s=S(D(V(row,"reference")),"source_field_sha256");return s==""?S(row,"sha256"):s;}
 static bool Integer(object o){return o is int||o is long;}
 static bool RefValid(Dictionary<string,object>r,string eid,string field,Dictionary<string,object>source,Dictionary<string,object>row){if(S(r,"evidence_id")!=eid||S(r,"source_field")!=field||S(r,"source")!=S(source,"source")||S(r,"source_field_sha256")!=Sha(Body(row))||!Integer(V(r,"start"))||!Integer(V(r,"end")))return false;int a=Convert.ToInt32(r["start"]),b=Convert.ToInt32(r["end"]);return a>=0&&b>=a&&b<=Count(Body(row));}
 static void Anchor(StringBuilder b,string eid,string field,Dictionary<string,object>source,Dictionary<string,object>row,string text,int start,int end){string url=S(row,"url");if(url=="")url=S(source,"url");b.AppendLine("  "+eid+" / "+field+" | "+Role(row)+" | автор (metadata): "+Author(row)).AppendLine("  "+url).AppendLine("  codepoint ["+start+", "+end+") | SHA256 поля: "+Sha(Body(row))).AppendLine("  Точный фрагмент: "+text);}
 public static List<Entry> Audit(string caseId,Dictionary<string,object>catalog,Dictionary<string,object>output){var result=new List<Entry>();var sources=D(V(catalog,"sources"));var modelSources=D(V(output,"sources"));string snapshot=Sha(new JavaScriptSerializer{MaxJsonLength=8388608}.Serialize(catalog));foreach(var sp in sources){string eid=sp.Key;var source=D(sp.Value);var fields=D(V(source,"fields"));var modelSource=D(V(modelSources,eid));foreach(var fp in fields){string field=fp.Key;var row=D(fp.Value);string body=Body(row);var model=D(V(modelSource,field));bool sourceScoped=model.Count==0&&modelSource.ContainsKey("disposition");if(sourceScoped)model=modelSource;var reference=D(V(model,"reference"));bool hash=ExpectedHash(row)!=""&&ExpectedHash(row)==Sha(body);bool bound=!sourceScoped&&hash&&RefValid(reference,eid,field,source,row);var e=new Entry{CaseId=caseId,EvidenceId=eid,Field=field,Role=Role(row),Author=Author(row),Url=S(row,"url")==""?S(source,"url"):S(row,"url"),SourceHashValid=hash,ReferenceValid=bound};
 var b=new StringBuilder("ПРОИСХОЖДЕНИЕ: сохранённые данные и интерпретация модели разделены.\r\nСмысл, независимость автора, истинность и спрос НЕ ДОКАЗАНЫ.\r\n");b.AppendLine("Набор: "+caseId+" | catalog projection SHA: "+snapshot).AppendLine("E-ID действует только внутри этого снимка; совпадение E-ID не связывает разные URL.").AppendLine("Хеш источника: "+(hash?"совпадает":"НЕ СОВПАДАЕТ / отсутствует; происхождение не подтверждено")).AppendLine("Ссылка модели на поле: "+(bound?"идентификаторы/хеш/диапазон совпадают; это не проверка смысла":"не подтверждена или не дана; вывод недоказан"));
 b.AppendLine().AppendLine("ИСТОЧНИК — полный сохранённый текст, не вывод модели:");Anchor(b,eid,field,source,row,body,0,Count(body));b.AppendLine("Границы — Unicode codepoints исходного поля, не UTF16 и не байты. Даты источника не обновлялись.");
 if(bound)b.AppendLine("Фрагмент, указанный ссылкой модели: "+Slice(body,Convert.ToInt32(reference["start"]),Convert.ToInt32(reference["end"])));
 b.AppendLine().AppendLine("МОДЕЛЬ — непроверенная интерпретация:");b.AppendLine("Статус/отказ модели: "+S(model,"status")+S(model,"disposition"));if(sourceScoped)b.AppendLine("Отказ дан для источника целиком, не атрибутирован этому полю. Требование готового решения/покупателя не является свидетельством из источника.");
 foreach(var act in A(V(model,"message_acts")))b.AppendLine("Акт сообщения по мнению модели: "+act+"; роль источника по metadata: "+e.Role+". Акт не проверен по смыслу; роль и акт не равнозначны.");
 var claims=new List<KeyValuePair<string,string>>();foreach(string key in new[]{"summary_as_attributed_message","reason"})if(S(model,key)!="")claims.Add(new KeyValuePair<string,string>(key,S(model,key)));foreach(string key in new[]{"qualifiers_and_negations","unknowns_explicitly_stated_by_author"})foreach(var x in A(V(model,key)))claims.Add(new KeyValuePair<string,string>(key,Convert.ToString(x)));
 foreach(var claim in claims){e.ModelClaims++;b.AppendLine().AppendLine(claim.Key+": "+claim.Value);int refStart=bound?Convert.ToInt32(reference["start"]):0;string scoped=bound?Slice(body,refStart,Convert.ToInt32(reference["end"])):"";int own=scoped.IndexOf(claim.Value,StringComparison.Ordinal);if(hash&&bound&&own>=0){b.AppendLine("Буквальное совпадение в указанном поле. Семантическая поддержка НЕ установлена.");Anchor(b,eid,field,source,row,claim.Value,refStart+Count(scoped.Substring(0,own)),refStart+Count(scoped.Substring(0,own+claim.Value.Length)));}else{b.AppendLine("НЕТ подтверждённой буквальной опоры в указанном поле; это не доказывает ложность, но вывод остаётся недоказанным.");if(hash&&!sourceScoped)foreach(var other in fields){if(other.Key==field)continue;var otherRow=D(other.Value);string otherBody=Body(otherRow);int at=otherBody.IndexOf(claim.Value,StringComparison.Ordinal);if(at>=0&&ExpectedHash(otherRow)==Sha(otherBody)){e.CrossFieldMatches++;b.AppendLine("ВНИМАНИЕ: буквальный фрагмент найден В ДРУГОМ ПОЛЕ. Нельзя переносить его автору текущего поля.");Anchor(b,eid,other.Key,source,otherRow,claim.Value,Count(otherBody.Substring(0,at)),Count(otherBody.Substring(0,at+claim.Value.Length)));}}}}
 b.AppendLine().AppendLine("ИТОГ: SEMANTICS_UNVERIFIED; DEMAND_UNVERIFIED; AUTO_ADMISSION=false. Буквальная цитата не доказывает смысл, платёж или спрос. Не найденное совпадение не доказывает, что утверждение добавлено моделью: возможен пересказ. Нужна ручная оценка точного источника.");e.Text=b.ToString();result.Add(e);}}return result;}
 static Dictionary<string,object>Read(string p){var f=new FileInfo(p);if(f.Length>8388608)throw new InvalidDataException("Audit file exceeds8MiB");return new JavaScriptSerializer{MaxJsonLength=8388608,RecursionLimit=128}.Deserialize<Dictionary<string,object>>(File.ReadAllText(p,Encoding.UTF8));}
 static string FileSha(string p){if(new FileInfo(p).Length>8388608)throw new InvalidDataException("Audit file exceeds8MiB");using(var h=SHA256.Create())using(var f=File.OpenRead(p))return BitConverter.ToString(h.ComputeHash(f)).Replace("-","").ToLowerInvariant();}
 public static List<Entry>Load(string root){string dir=Path.Combine(root,"attribution-cases"),manifest=Path.Combine(dir,"cases.json");var all=new List<Entry>();if(!File.Exists(manifest))return all;foreach(var x in A(V(Read(manifest),"cases"))){var item=D(x);string id=S(item,"id");try{foreach(string key in new[]{"catalog","output","input","response"}){string name=S(item,key);if(name==""||Path.GetFileName(name)!=name)throw new InvalidDataException("Local audit names only");if(FileSha(Path.Combine(dir,name))!=S(item,key+"_sha256"))throw new InvalidDataException("Saved case hash changed: "+key);}var catalog=Read(Path.Combine(dir,S(item,"catalog")));var output=Read(Path.Combine(dir,S(item,"output")));ValidateBindings(catalog,output,Read(Path.Combine(dir,S(item,"input"))),Read(Path.Combine(dir,S(item,"response"))));var loaded=Audit(id,catalog,output);foreach(var row in loaded)row.Text="Архивная связка input→catalog и response→output проверена. Это не проверка смысла.\r\nТочный SHA файла catalog: "+S(item,"catalog_sha256")+"\r\n"+row.Text;all.AddRange(loaded);}catch(Exception ex){all.Add(new Entry{CaseId=id,EvidenceId="ERROR",Field="",Role="",Text="Набор не проверен: "+ex.Message+"\r\nОстальные наборы доступны; файлы не исправлялись."});}}return all;}
 public static string DescribeObservation(Dictionary<string,object>row){var b=new StringBuilder("ПРОИСХОЖДЕНИЕ СОХРАНЁННЫХ ПОЛЕЙ: авторы раздельны, истинность/спрос не проверены.\r\n");b.AppendLine("Снимок: "+S(row,"observation_snapshot_id")+" | observation_id: "+S(row,"observation_id")).AppendLine("E-ID только внутри снимка: "+S(row,"evidence_id"));foreach(string field in new[]{"context_text","answer_text"}){string body=S(row,field);if(body=="")continue;bool answer=field=="answer_text";string expected=S(row,answer?"answer_text_sha256":"context_text_sha256"),author=S(row,answer?"answer_author_id":"author_id"),url=S(row,answer?"answer_url":"url");b.AppendLine("Поле "+field+" | "+(answer?"отдельный ответ":"контекст: "+S(row,"content_scope"))+" | автор(metadata): "+(author==""?"не установлен":author)).AppendLine(url).AppendLine("codepoint [0,"+Count(body)+") | SHA256: "+Sha(body)+" | проверка сохранённого hash: "+(expected==""?"нет":expected==Sha(body)?"совпадает":"НЕ СОВПАДАЕТ"));}return b.ToString();}
}
